   --bg-raised: #0e1014;
   --text: #f1f2f4;
   --muted: #a2a7b3;
   --faint: #71767f;
   --accent: #8b8cf8;
   --accent-strong: #6366f1;
   --green: #4ade80;
   --amber: #f0b34a;
   --line: rgba(255, 255, 255, 0.07);
