   clip: rect(0, 0, 0, 0);
   white-space: nowrap;
   border: 0;
 }

 /* ------------------------------------------------------------------ */
 /* Shell                                                              */
 /* ------------------------------------------------------------------ */
 .studio-app {
   height: 100dvh;
   display: grid;
   grid-template-columns: var(--sidebar-width) minmax(0, 1fr);
