+import { useState } from "react";
+
+import { useStudio } from "../../state/StudioContext";
+import type { StudioBrief } from "../../types";
+
+
+interface Draft {
+  product_name: string;
+  product_url: string;
+  target_user: string;
+  job_statement: string;
+  core_problem: string;
+  display_name: string;
+}
+
+const STEPS = ["The work", "The person", "The friction"] as const;
+
+/**
+ * First run sets the context the whole studio depends on: what is being built,
+ * who it serves, the job they are trying to get done, and where it hurts.
+ *
+ * A deterministic form, not a chat, so it can be completed with no model.
+ */
+export function Onboarding() {
+  const {
+    brief,
+    displayName,
+    setDisplayName,
+    saveBrief,
+    closeOnboarding,
+    createJob,
+    clearChat,
+    closePanel,
+    pushToast,
+  } = useStudio();
+
+  const [step, setStep] = useState(0);
+  const [draft, setDraft] = useState<Draft>({
+    product_name: brief?.product_name ?? "",
+    product_url: brief?.product_url ?? "",
+    target_user: brief?.target_user ?? "",
+    job_statement: brief?.job_statement ?? "",
+    core_problem: brief?.core_problem ?? "",
+    display_name: displayName,
+  });
+  const [submitting, setSubmitting] = useState(false);
+  const editing = Boolean(brief);
+
+  function update<K extends keyof Draft>(key: K, value: Draft[K]) {
+    setDraft((prev) => ({ ...prev, [key]: value }));
+  }
+
+  const stepValid =
+    step === 0
+      ? draft.product_name.trim().length > 0
+      : step === 1
+        ? draft.target_user.trim().length > 0 && draft.job_statement.trim().length > 0
+        : true;
+
+  async function finish() {
+    if (submitting) {
+      return;
+    }
+    setSubmitting(true);
+    const context: StudioBrief = {
+      product_name: draft.product_name.trim(),
+      product_url: draft.product_url.trim() || undefined,
+      target_user: draft.target_user.trim(),
+      job_statement: draft.job_statement.trim(),
+      core_problem: draft.core_problem.trim(),
+    };
+    const jobName = context.job_statement || context.product_name;
+    const description = [context.target_user, context.core_problem].filter(Boolean).join(" — ");
+    const jobId = await createJob({ name: jobName, description: description || undefined });
+    saveBrief({ ...context, job_id: jobId ?? brief?.job_id });
+    if (draft.display_name.trim() !== displayName) {
+      setDisplayName(draft.display_name.trim());
+    }
+    clearChat();
+    closePanel();
+    pushToast("success", "Context saved. Every reply now starts from your job.");
+    setSubmitting(false);
+  }
+
+  return (
+    <div className="onboarding" role="dialog" aria-modal="true" aria-labelledby="onboarding-title">
+      <div className="onboarding__panel">
+        <header className="onboarding__head">
+          <p className="onboarding__eyebrow">
+            {editing ? "Your context" : "Before we begin"} · Step {step + 1} of {STEPS.length}
+          </p>
+          <h1 id="onboarding-title" className="onboarding__title">
+            {step === 0 && "What are you building?"}
+            {step === 1 && "Who is it for, and what job are they doing?"}
+            {step === 2 && "Where do they get stuck?"}
+          </h1>
+        </header>
+
+        <div className="onboarding__progress" role="list" aria-label="Progress">
+          {STEPS.map((label, index) => (
+            <span
+              key={label}
+              role="listitem"
+              className={`onboarding__dot${index === step ? " is-current" : ""}${
+                index < step ? " is-done" : ""
+              }`}
+              aria-current={index === step ? "step" : undefined}
+            >
+              {label}
+            </span>
+          ))}
+        </div>
+
+        <form
+          className="onboarding__form"
+          onSubmit={(event) => {
+            event.preventDefault();
+            if (step < STEPS.length - 1) {
+              if (stepValid) {
+                setStep((prev) => prev + 1);
+              }
+              return;
+            }
+            void finish();
+          }}
+        >
+          {step === 0 && (
+            <>
+              <div className="field">
+                <label htmlFor="ob-product">Product name</label>
+                <input
+                  id="ob-product"
+                  className="input"
+                  value={draft.product_name}
+                  autoFocus
+                  placeholder="Ambient"
+                  onChange={(event) => update("product_name", event.target.value)}
+                />
+              </div>
+              <div className="field">
+                <label htmlFor="ob-url">
+                  Product URL <span className="field__hint">optional</span>
+                </label>
+                <input
+                  id="ob-url"
+                  className="input"
+                  value={draft.product_url}
+                  placeholder="https://ambient.dev"
+                  spellCheck={false}
+                  onChange={(event) => update("product_url", event.target.value)}
+                />
+              </div>
+            </>
+          )}
+
+          {step === 1 && (
+            <>
+              <div className="field">
+                <label htmlFor="ob-user">Who is the customer?</label>
+                <input
+                  id="ob-user"
+                  className="input"
+                  value={draft.target_user}
+                  autoFocus
+                  placeholder="Platform engineers shipping services"
+                  onChange={(event) => update("target_user", event.target.value)}
+                />
+              </div>
+              <div className="field">
+                <label htmlFor="ob-job">What job are they trying to get done?</label>
+                <textarea
+                  id="ob-job"
+                  className="input input--area"
+                  rows={3}
+                  value={draft.job_statement}
+                  placeholder="Get a service from a local commit to production without hand-copying configuration."
+                  onChange={(event) => update("job_statement", event.target.value)}
+                />
+                <p className="field__hint">
+                  Describe the progress they are trying to make, not a feature. This becomes your
+                  first Job.
+                </p>
+              </div>
+            </>
+          )}
+
+          {step === 2 && (
+            <>
+              <div className="field">
+                <label htmlFor="ob-problem">Where does it hurt most?</label>
+                <textarea
+                  id="ob-problem"
+                  className="input input--area"
+                  rows={3}
+                  value={draft.core_problem}
+                  autoFocus
+                  placeholder="A missed config key costs hours on deploy day."
+                  onChange={(event) => update("core_problem", event.target.value)}
+                />
+                <p className="field__hint">
+                  One frustration is enough. You will turn it into scored outcomes next.
+                </p>
+              </div>
+              <div className="field">
+                <label htmlFor="ob-name">
+                  What should I call you? <span className="field__hint">optional</span>
+                </label>
+                <input
+                  id="ob-name"
+                  className="input"
+                  value={draft.display_name}
+                  placeholder="Ada"
+                  autoComplete="given-name"
+                  onChange={(event) => update("display_name", event.target.value)}
+                />
+              </div>
+
+              <div className="onboarding__preview" aria-label="Your context">
+                <p className="onboarding__preview-label">Here is what the studio will hold</p>
+                <dl>
+                  <div>
+                    <dt>Product</dt>
+                    <dd>{draft.product_name || "—"}</dd>
+                  </div>
+                  <div>
+                    <dt>Customer</dt>
+                    <dd>{draft.target_user || "—"}</dd>
+                  </div>
+                  <div>
+                    <dt>Job</dt>
+                    <dd>{draft.job_statement || "—"}</dd>
+                  </div>
+                  <div>
+                    <dt>Friction</dt>
+                    <dd>{draft.core_problem || "—"}</dd>
+                  </div>
+                </dl>
+              </div>
+            </>
+          )}
+
+          <div className="onboarding__actions">
+            <button
+              type="button"
+              className="button button--ghost"
+              onClick={() => {
+                if (step === 0) {
+                  closeOnboarding();
+                } else {
+                  setStep((prev) => prev - 1);
+                }
+              }}
+            >
+              {step === 0 ? "I'll do this later" : "Back"}
+            </button>
+            <button type="submit" className="button" disabled={!stepValid || submitting}>
+              {step < STEPS.length - 1
+                ? "Continue"
+                : submitting
+                  ? "Saving…"
+                  : editing
+                    ? "Save context"
+                    : "Open the studio"}
+            </button>
+          </div>
+        </form>
+      </div>
+    </div>
+  );
+}

