   const deleteOutcome = useCallback(
     async (outcomeId: string) => {
       try {
         await apiDeleteOutcome(outcomeId, settings.mcp_url);
         pushToast("success", "Outcome removed.");
         await refreshCanvas();
       } catch (error) {
         pushToast("error", `Could not remove the outcome: ${(error as Error).message}`);
       }
     },
     [settings.mcp_url, pushToast, refreshCanvas],
   );

   const clearPendingSimOutcome = useCallback(() => setPendingSimOutcome(null), []);

   const closePanel = useCallback(() => setActivePanel(null), []);

   const openPanel = useCallback((panel: WorkspacePanelId) => {
     setActivePanel(panel);
   }, []);

   const requestSimulate = useCallback((outcomeId: string) => {
     setPendingSimOutcome(outcomeId);
     setActivePanel("impact");
   }, []);

   const stopStreaming = useCallback(() => {
     abortRef.current?.abort();
   }, []);

   const sendMessage = useCallback(
     async (text: string) => {
       const trimmed = text.trim();
       if (!trimmed || streaming) {
         return;
       }

       const history: ChatMessage[] = [...messages, { role: "user", content: trimmed }];
       setMessages([...history, { role: "assistant", content: "" }]);
       setStreaming(true);
       setThinkingPhase("health_check");
       setOfflineReply(false);
       setToolActivity([]);

       const controller = new AbortController();
       abortRef.current = controller;

       let content = "";

       const handleEvent = (event: RawSseEvent) => {
         switch (event.event) {
           case "status": {
             const phase = String(event.data.phase ?? "");
             setThinkingPhase(phase);
             if (phase === "offline") {
               setOfflineReply(true);
             }
             break;
           }
           case "delta": {
             content += String(event.data.text ?? "");
             setMessages((prev) => {
               const next = [...prev];
               next[next.length - 1] = { role: "assistant", content };
               return next;
             });
             break;
           }
           case "tool":
             setToolActivity((prev) => [
               ...prev,
               {
                 name: String(event.data.name ?? ""),
                 status: String(event.data.status ?? ""),
                 preview: event.data.preview ? String(event.data.preview) : undefined,
               },
             ]);
             break;
           case "message":
             content = String(event.data.content ?? content);
             setMessages((prev) => {
               const next = [...prev];
               next[next.length - 1] = { role: "assistant", content };
               return next;
             });
             break;
           case "canvas_dirty":
             void refreshCanvas();
             break;
           case "error":
             pushToast("error", String(event.data.message ?? "Unknown chat error"));
             break;
           default:
             break;
         }
       };

       try {
         await streamChat(
           {
             base_url: settings.base_url,
             api_key: settings.api_key,
             model: settings.model_name,
             mcp_url: settings.mcp_url,
             messages: history,
             brief,
           },
           handleEvent,
           controller.signal,
         );
       } catch (error) {
         const aborted = (error as Error).name === "AbortError";
         if (!aborted) {
           pushToast("error", `Error during assistant completion: ${(error as Error).message}`);
         }
         if (!content) {
           setMessages((prev) => {
             const next = [...prev];
             if (next.length && next[next.length - 1].content === "") {
               next.pop();
             }
             return next;
           });
         }
       } finally {
         setStreaming(false);
         setThinkingPhase(null);
         abortRef.current = null;
       }
     },
     [messages, streaming, settings, brief, refreshCanvas, pushToast],
   );

   const clearChat = useCallback(() => {
     abortRef.current?.abort();
     abortRef.current = null;
     setMessages([]);
     setToolActivity([]);
     setStreaming(false);
     setThinkingPhase(null);
     setOfflineReply(false);
   }, []);

   // Initial hydration: env defaults, canvas, health probes.
   useEffect(() => {
     let cancelled = false;

     async function boot() {
       try {
         const defaults = await fetchConfig();
         if (!cancelled && localStorage.getItem(SETTINGS_KEY) === null) {
           saveSettings(defaults);
         }
       } catch {
         /* sidecar not reachable; keep local fallback defaults */
       }
       if (cancelled) {
         return;
       }
       void refreshCanvas();
       void healthMcp(settings.mcp_url)
         .then((result) => {
           if (!cancelled) {
             setMcpReachable(result.reachable);
           }
         })
         .catch(() => undefined);
       void healthLlm({
         base_url: settings.base_url,
         api_key: settings.api_key,
         model: settings.model_name,
       })
         .then((result) => {
           if (!cancelled) {
             setLlmHealth(result);
           }
         })
         .catch(() => undefined);
     }

     void boot();
     return () => {
       cancelled = true;
     };
     // eslint-disable-next-line react-hooks/exhaustive-deps
   }, []);

   const value = useMemo<StudioContextValue>(
     () => ({
       settings,
       saveSettings,
       displayName,
       setDisplayName,
       brief,
       saveBrief,
       onboardingOpen,
       openOnboarding,
       closeOnboarding,
       canvas,
       canvasLoading,
       canvasCached,
       refreshCanvas,
       llmHealth,
       mcpReachable,
       messages,
       streaming,
       thinkingPhase,
       toolActivity,
       sendMessage,
       stopStreaming,
       clearChat,
       pushNotice,
       offlineReply,
       addStep,
       addOutcome,
       createJob,
       updateJob,
       deleteJob,
       updateStep,
       deleteStep,
       updateOutcome,
       deleteOutcome,
       pendingSimOutcome,
       requestSimulate,
       clearPendingSimOutcome,
       activePanel,
       openPanel,
       closePanel,
       toasts,
       pushToast,
       dismissToast,
     }),
     [
       settings,
       saveSettings,
       displayName,
       setDisplayName,
       brief,
       saveBrief,
       onboardingOpen,
       openOnboarding,
       closeOnboarding,
       canvas,
       canvasLoading,
       canvasCached,
       refreshCanvas,
       llmHealth,
       mcpReachable,
       messages,
       streaming,
       thinkingPhase,
       toolActivity,
       sendMessage,
       stopStreaming,
       clearChat,
       pushNotice,
       offlineReply,
       addStep,
       addOutcome,
       createJob,
       updateJob,
       deleteJob,
       updateStep,
       deleteStep,
       updateOutcome,
       deleteOutcome,
       pendingSimOutcome,
       requestSimulate,
       clearPendingSimOutcome,
       activePanel,
       openPanel,
       closePanel,
       toasts,
       pushToast,
       dismissToast,
     ],
   );

   return <StudioContext.Provider value={value}>{children}</StudioContext.Provider>;
 }

 export function useStudio(): StudioContextValue {
   const context = useContext(StudioContext);
   if (!context) {
     throw new Error("useStudio must be used within a StudioProvider");
   }
   return context;
 }

