+            disabled={!outcome.id}
+            onClick={() => {
+              if (!confirmDelete) {
+                setConfirmDelete(true);
+                return;
+              }
+              setConfirmDelete(false);
+              void deleteOutcome(outcomeId);
+            }}
+          >
+            {confirmDelete ? "Confirm remove" : "Remove"}
+          </button>
+        )}
